BEGIN TRANSACTION;
CREATE TABLE "changeover_matrix" ("changeover_id" TEXT, "from_family" TEXT, "to_family" TEXT, "duration_minutes" TEXT, "effective_from" TEXT, "effective_to" TEXT);
CREATE TABLE "inventory_lots" ("lot_id" TEXT, "material_id" TEXT, "initial_quantity" TEXT, "available_from" TEXT, "expiry_at" TEXT, "reserved_quantity" TEXT, "consumed_quantity" TEXT, "remaining_quantity" TEXT, "status" TEXT);
CREATE TABLE "inventory_transactions" ("transaction_id" TEXT, "lot_id" TEXT, "material_id" TEXT, "order_id" TEXT, "operation_id" TEXT, "schedule_id" TEXT, "event_type" TEXT, "quantity" TEXT, "event_at" TEXT, "allocation_policy" TEXT);
CREATE TABLE "labor_calendars" ("labor_calendar_id" TEXT, "skill" TEXT, "shift_date" TEXT, "shift_no" TEXT, "start_at" TEXT, "end_at" TEXT, "workers_available" TEXT);
CREATE TABLE "labor_requirements" ("labor_requirement_id" TEXT, "route_operation_id" TEXT, "skill" TEXT, "workers_required" TEXT);
CREATE TABLE "machine_calendars" ("calendar_id" TEXT, "machine_id" TEXT, "shift_date" TEXT, "shift_no" TEXT, "start_at" TEXT, "end_at" TEXT, "capacity_minutes" TEXT, "availability" TEXT, "reason" TEXT);
CREATE TABLE "machine_downtime" ("downtime_id" TEXT, "machine_id" TEXT, "start_at" TEXT, "end_at" TEXT, "reason" TEXT);
CREATE TABLE "machine_eligibility" ("route_operation_id" TEXT, "machine_id" TEXT, "effective_from" TEXT, "effective_to" TEXT);
CREATE TABLE "machines" ("machine_id" TEXT, "name" TEXT, "process_family" TEXT, "capacity_units_per_shift" TEXT, "status" TEXT);
CREATE TABLE "material_requirements" ("requirement_id" TEXT, "order_id" TEXT, "operation_id" TEXT, "material_id" TEXT, "quantity_per_unit" TEXT, "required_quantity" TEXT, "unit" TEXT, "available_date" TEXT, "available_at" TEXT);
CREATE TABLE "materials" ("material_id" TEXT, "name" TEXT, "unit" TEXT, "status" TEXT);
CREATE TABLE "operation_schedules" ("schedule_id" TEXT, "order_id" TEXT, "operation_id" TEXT, "machine_id" TEXT, "sequence_no" TEXT, "start_at" TEXT, "end_at" TEXT, "quantity" TEXT, "setup_minutes" TEXT, "changeover_minutes" TEXT, "run_minutes" TEXT, "status" TEXT);
CREATE TABLE "operations" ("route_operation_id" TEXT, "routing_id" TEXT, "sequence_no" TEXT, "name" TEXT, "process_family" TEXT, "product_family" TEXT, "run_minutes_per_unit" TEXT, "setup_minutes" TEXT);
CREATE TABLE "order_operations" ("operation_id" TEXT, "order_id" TEXT, "routing_id" TEXT, "route_operation_id" TEXT, "sequence_no" TEXT, "status" TEXT);
CREATE TABLE "production_orders" ("order_id" TEXT, "product_id" TEXT, "routing_id" TEXT, "quantity" TEXT, "order_date" TEXT, "due_date" TEXT, "priority" TEXT, "status" TEXT);
CREATE TABLE "products" ("product_id" TEXT, "sku" TEXT, "description" TEXT, "family" TEXT, "status" TEXT);
CREATE TABLE "routings" ("routing_id" TEXT, "product_id" TEXT, "revision" TEXT, "effective_from" TEXT, "effective_to" TEXT, "status" TEXT);
CREATE TABLE "tool_availability" ("tool_availability_id" TEXT, "tool_id" TEXT, "shift_date" TEXT, "shift_no" TEXT, "available_quantity" TEXT);
CREATE TABLE "tool_requirements" ("tool_requirement_id" TEXT, "route_operation_id" TEXT, "tool_id" TEXT, "units_required" TEXT);
CREATE TABLE "tools" ("tool_id" TEXT, "name" TEXT, "copies" TEXT, "status" TEXT);
COMMIT;
